components.css:
.ds-btn-primary {
  background: #6c72f0;
  color: #ffffff;
  padding: 8px 16px;
  border: none;
  border-radius: 12px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: -0.01em;
  cursor: pointer;
  transition: background-color 180ms cubic-bezier(0.25, 0.1, 0.25, 1);
}
.ds-btn-primary:hover {
  background: #8187f5;
}
.ds-btn-primary:focus-visible {
  outline: 2px solid #6c72f0;
  outline-offset: 2px;
}
.ds-btn-primary:active {
  background: #5a60e0;
}
.ds-btn-primary:disabled {
  background: #1a1d2b;
  color: #787d94;
  cursor: not-allowed;
}

.ds-btn-ghost {
  background: transparent;
  color: #9498b0;
  padding: 6px 12px;
  border: none;
  border-radius: 8px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: -0.01em;
  cursor: pointer;
  transition: background-color 180ms cubic-bezier(0.25, 0.1, 0.25, 1), color 180ms cubic-bezier(0.25, 0.1, 0.25, 1);
}
.ds-btn-ghost:hover {
  background: #1a1d2b;
  color: #e8e9f0;
}
.ds-btn-ghost:focus-visible {
  outline: 2px solid #6c72f0;
  outline-offset: 2px;
}

.ds-chip-category {
  background: transparent;
  color: #9498b0;
  padding: 6px 16px;
  border: none;
  border-radius: 8px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 180ms cubic-bezier(0.25, 0.1, 0.25, 1), color 180ms cubic-bezier(0.25, 0.1, 0.25, 1);
}
.ds-chip-category:hover {
  background: #1a1d2b;
  color: #e8e9f0;
}
.ds-chip-category:focus-visible {
  outline: 2px solid #6c72f0;
  outline-offset: 2px;
}
.ds-chip-category--selected {
  background: #6c72f0;
  color: #ffffff;
}
.ds-chip-category--selected:hover {
  background: #8187f5;
  color: #ffffff;
}

.ds-card {
  background: #13151f;
  border: 1px solid #232738;
  border-radius: 16px;
  overflow: hidden;
  cursor: pointer;
  transition: border-color 180ms cubic-bezier(0.25, 0.1, 0.25, 1), box-shadow 180ms cubic-bezier(0.25, 0.1, 0.25, 1);
}
.ds-card:hover {
  border-color: #2f3454;
  box-shadow: 0 0 20px rgba(108, 114, 240, 0.08);
}
.ds-card-body {
  padding: 14px 16px;
}

.ds-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}
.ds-input-icon {
  position: absolute;
  left: 14px;
  width: 16px;
  height: 16px;
  color: #787d94;
  pointer-events: none;
}
.ds-input {
  width: 100%;
  background: #0a0b10;
  color: #e8e9f0;
  padding: 10px 14px 10px 38px;
  border: 1px solid #232738;
  border-radius: 12px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  font-size: 14px;
  outline: none;
  transition: border-color 180ms cubic-bezier(0.25, 0.1, 0.25, 1);
}
.ds-input::placeholder {
  color: #787d94;
  font-size: 13px;
}
.ds-input:focus {
  border-color: #6c72f0;
  outline: 2px solid #6c72f0;
  outline-offset: 2px;
}
.ds-input:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.ds-chat-input {
  flex: 1;
  background: #0a0b10;
  color: #e8e9f0;
  padding: 10px 14px;
  border: 1px solid #232738;
  border-radius: 12px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  font-size: 13px;
  line-height: 1.5;
  outline: none;
  resize: none;
  transition: border-color 180ms cubic-bezier(0.25, 0.1, 0.25, 1);
}
.ds-chat-input::placeholder {
  color: #787d94;
}
.ds-chat-input:focus {
  border-color: #6c72f0;
  outline: 2px solid #6c72f0;
  outline-offset: 2px;
}
.ds-chat-input:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.ds-nav {
  height: 44px;
  display: flex;
  align-items: center;
  padding: 0 20px;
  gap: 20px;
  background: #13151f;
  border-bottom: 1px solid #232738;
  flex-shrink: 0;
}
.ds-nav-logo {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: #e8e9f0;
  text-decoration: none;
  transition: color 180ms cubic-bezier(0.25, 0.1, 0.25, 1);
}
.ds-nav-logo:hover {
  color: #ffffff;
}
.ds-nav-links {
  display: flex;
  gap: 4px;
}
.ds-nav-link {
  padding: 6px 12px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: -0.01em;
  color: #9498b0;
  text-decoration: none;
  transition: background-color 180ms cubic-bezier(0.25, 0.1, 0.25, 1), color 180ms cubic-bezier(0.25, 0.1, 0.25, 1);
}
.ds-nav-link:hover {
  background: #1a1d2b;
  color: #e8e9f0;
}
.ds-nav-link:focus-visible,
.ds-nav-logo:focus-visible {
  outline: 2px solid #6c72f0;
  outline-offset: 2px;
  border-radius: 2px;
}

.ds-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  max-width: 360px;
  margin: 0 auto;
  min-height: 50vh;
}
.ds-empty-icon {
  width: 64px;
  height: 64px;
  border-radius: 16px;
  background: rgba(108, 114, 240, 0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 20px;
}
.ds-empty-title {
  font-size: 18px;
  font-weight: 600;
  color: #e8e9f0;
  margin-bottom: 8px;
}
.ds-empty-desc {
  font-size: 14px;
  color: #9498b0;
  line-height: 1.6;
  margin-bottom: 24px;
}
.ds-empty-arrow {
  width: 16px;
  height: 16px;
  margin-left: 4px;
}

.ds-proj-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 16px;
  background: #13151f;
  border: 1px solid #232738;
  border-radius: 16px;
  cursor: pointer;
  transition: border-color 180ms cubic-bezier(0.25, 0.1, 0.25, 1), box-shadow 180ms cubic-bezier(0.25, 0.1, 0.25, 1);
}
.ds-proj-item:hover {
  border-color: #2f3454;
  box-shadow: 0 0 20px rgba(108, 114, 240, 0.08);
}
.ds-proj-item:focus-visible {
  outline: 2px solid #6c72f0;
  outline-offset: 2px;
}
.ds-proj-icon {
  width: 36px;
  height: 36px;
  border-radius: 12px;
  background: #0a0b10;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  flex-shrink: 0;
}
.ds-proj-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.ds-proj-name {
  font-size: 14px;
  font-weight: 500;
  color: #e8e9f0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ds-proj-date {
  font-size: 12px;
  color: #787d94;
}
.ds-proj-arrow {
  font-size: 14px;
  color: #787d94;
  transition: color 180ms ease-out, transform 200ms ease-out;
  flex-shrink: 0;
}
.ds-proj-item:hover .ds-proj-arrow {
  color: #6c72f0;
  transform: translateX(2px);
}

.ds-spinner {
  width: 24px;
  height: 24px;
  border: 2px solid #232738;
  border-top-color: #6c72f0;
  border-radius: 50%;
  animation: ds-spin 0.8s linear infinite;
}
@keyframes ds-spin {
  to { transform: rotate(360deg); }
}
@media (prefers-reduced-motion: reduce) {
  .ds-spinner { animation: none; }
}
